#define _GNU_SOURCE
#include <lean/lean.h>
#include <dlfcn.h>
#include <string.h>
#include <unistd.h>

lean_obj_res lean_io_app_path(lean_obj_arg world) {
    (void)world;
    return lean_io_result_mk_ok(
        lean_mk_string("/opt/elan/toolchains/leanprover--lean4---v4.22.0/bin/lean"));
}

ssize_t readlink(const char *path, char *buffer, size_t size) {
    typedef ssize_t (*readlink_fn)(const char *, char *, size_t);
    static readlink_fn next_readlink;
    if (!next_readlink)
        next_readlink = (readlink_fn)dlsym(RTLD_NEXT, "readlink");
    if (strncmp(path, "/proc/", 6) == 0 &&
        strlen(path) > 10 &&
        strcmp(path + strlen(path) - 4, "/exe") == 0)
        path = "/proc/self/exe";
    return next_readlink(path, buffer, size);
}

