#define _GNU_SOURCE
#include <dlfcn.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

static int is_proc_exe(const char *path) {
  size_t n = strlen(path);
  return strncmp(path, "/proc/", 6) == 0 && n >= 4 &&
         strcmp(path + n - 4, "/exe") == 0;
}

ssize_t readlink(const char *path, char *buf, size_t size) {
  if (is_proc_exe(path)) {
    const char *lean = "/opt/elan/toolchains/leanprover--lean4---v4.22.0/bin/lean";
    size_t n = strlen(lean);
    if (n > size) n = size;
    memcpy(buf, lean, n);
    return (ssize_t)n;
  }
  static ssize_t (*real_readlink)(const char *, char *, size_t);
  if (!real_readlink)
    real_readlink = dlsym(RTLD_NEXT, "readlink");
  return real_readlink(path, buf, size);
}

ssize_t readlinkat(int dirfd, const char *path, char *buf, size_t size) {
  if (is_proc_exe(path)) {
    const char *lean = "/opt/elan/toolchains/leanprover--lean4---v4.22.0/bin/lean";
    size_t n = strlen(lean);
    if (n > size) n = size;
    memcpy(buf, lean, n);
    return (ssize_t)n;
  }
  static ssize_t (*real_readlinkat)(int, const char *, char *, size_t);
  if (!real_readlinkat)
    real_readlinkat = dlsym(RTLD_NEXT, "readlinkat");
  return real_readlinkat(dirfd, path, buf, size);
}
